int coop_hook(Cpu *c, uint64_t addr);
// The function-entry profiler's call with the whole Cpu: the co-op frame tracer reads x0..x3 (coop_trace.c
// coop_fnprof_hit, which also makes upstream's fnprof_hit call).
void coop_fnprof_hit(uint64_t addr, Cpu *c);
#undef FN_ENTER
#define FN_ENTER(a) do { if (COOP_HOOKED(a) && coop_hook(c, a)) return; if (__builtin_expect(g_fnprof, 0)) coop_fnprof_hit(a, c); } while (0)
